import {useDeferredValue,useEffect,useMemo,useState} from "react";
import {Search,ArrowUpRight,ChevronLeft,ChevronRight,X,Newspaper} from "lucide-react";
import {Input} from "./Input";
import {Button} from "./Button";
import {Select,SelectContent,SelectItem,SelectTrigger,SelectValue} from "./Select";
import styles from "./NewsBrowser.module.css";
type News={id:number;title:string;excerpt:string;date:string;url:string;categories:string[];image:string};
const normalize=(s:string)=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
const initial=()=>{const p=new URLSearchParams(typeof window==="undefined"?"":window.location.search);return {q:p.get("busca")||p.get("s")||"",category:p.get("categoria")||"all",year:p.get("ano")||"all",sort:p.get("ordem")||"recent"};};
export const NewsBrowser=()=>{
 const [filters,setFilters]=useState(initial);const [rows,setRows]=useState<News[]|null>(null);const [error,setError]=useState(false);const [page,setPage]=useState(1);const [attempt,setAttempt]=useState(0);const query=useDeferredValue(filters.q);
 useEffect(()=>{const c=new AbortController();setError(false);fetch("/_api/news",{signal:c.signal}).then(r=>{if(!r.ok)throw Error();return r.json();}).then(setRows).catch(()=>{if(!c.signal.aborted)setError(true);});return()=>c.abort();},[attempt]);
 useEffect(()=>{const p=new URLSearchParams();if(filters.q)p.set("busca",filters.q);if(filters.category!=="all")p.set("categoria",filters.category);if(filters.year!=="all")p.set("ano",filters.year);if(filters.sort!=="recent")p.set("ordem",filters.sort);window.history.replaceState(window.history.state,"",window.location.pathname+(p.size?"?"+p:""));},[filters]);
 const years=useMemo(()=>Array.from(new Set((rows||[]).map(r=>r.date.slice(0,4)))).sort().reverse(),[rows]);
 const categories=useMemo(()=>Array.from(new Set((rows||[]).flatMap(r=>r.categories))).sort((a,b)=>a.localeCompare(b,"pt-BR")),[rows]);
 const result=useMemo(()=>{const terms=normalize(query.trim()).split(/\s+/).filter(Boolean);return (rows||[]).filter(r=>(filters.category==="all"||r.categories.includes(filters.category))&&(filters.year==="all"||r.date.startsWith(filters.year))&&terms.every(t=>normalize(r.title+" "+r.excerpt).includes(t))).sort((a,b)=>filters.sort==="oldest"?a.date.localeCompare(b.date):filters.sort==="title"?a.title.localeCompare(b.title,"pt-BR"):b.date.localeCompare(a.date));},[rows,query,filters.category,filters.year,filters.sort]);
 const pages=Math.max(1,Math.ceil(result.length/12));const current=Math.min(page,pages);const visible=result.slice((current-1)*12,current*12);const active=filters.q||filters.category!=="all"||filters.year!=="all";
 const change=(key:keyof typeof filters,value:string)=>{setFilters(f=>({...f,[key]:value}));setPage(1);};
 const clear=()=>{setFilters({q:"",category:"all",year:"all",sort:"recent"});setPage(1);};
 const go=(next:number)=>{setPage(next);document.getElementById("noticias-resultados")?.scrollIntoView({behavior:"smooth",block:"start"});};
 return <section className={styles.news} aria-labelledby="news-title">
 <div className={styles.heading}><div><span className={styles.eyebrow}>ACOMPANHE NOSSAS AÇÕES</span><h1 id="news-title">Notícias</h1><p>Histórias, projetos e novidades que fazem parte da nossa trajetória.</p></div><span className={styles.total}><Newspaper size={18}/>{rows?rows.length:"…"} publicações</span></div>
 <div className={styles.toolbar}><label className={styles.search}><Search size={20}/><Input aria-label="Buscar notícias" placeholder="Buscar por título ou assunto…" value={filters.q} onChange={e=>change("q",e.target.value)}/>{filters.q&&<Button variant="ghost" size="icon-sm" aria-label="Apagar busca" onClick={()=>change("q","")}><X size={16}/></Button>}</label>
 <div className={styles.filter}><span>Categoria</span><Select value={filters.category} onValueChange={v=>change("category",v)}><SelectTrigger aria-label="Filtrar por categoria"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">Todas as categorias</SelectItem>{categories.map(c=><SelectItem key={c} value={c}>{c}</SelectItem>)}</SelectContent></Select></div>
 <div className={styles.filter}><span>Ano</span><Select value={filters.year} onValueChange={v=>change("year",v)}><SelectTrigger aria-label="Filtrar por ano"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">Todos os anos</SelectItem>{years.map(y=><SelectItem key={y} value={y}>{y}</SelectItem>)}</SelectContent></Select></div>
 <div className={styles.filter}><span>Ordenar por</span><Select value={filters.sort} onValueChange={v=>change("sort",v)}><SelectTrigger aria-label="Ordenar notícias"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="recent">Mais recentes</SelectItem><SelectItem value="oldest">Mais antigas</SelectItem><SelectItem value="title">Título: A–Z</SelectItem></SelectContent></Select></div></div>
 <div className={styles.resultBar} id="noticias-resultados"><p role="status" aria-live="polite">{rows?(result.length===1?"1 notícia encontrada":result.length+" notícias encontradas"):"Carregando notícias…"}</p>{active&&<Button variant="ghost" size="sm" onClick={clear}><X size={14}/>Limpar filtros</Button>}</div>
 {error?<div className={styles.empty}><h2>Não foi possível carregar as notícias.</h2><Button onClick={()=>setAttempt(n=>n+1)}>Tentar novamente</Button></div>:!rows?<div className={styles.grid}>{Array.from({length:6},(_,i)=><div className={styles.skeleton} key={i}/>)}</div>:visible.length?<div className={styles.grid}>{visible.map(row=><article className={styles.card} key={row.id}><a className={styles.image} href={row.url} tabIndex={-1} aria-hidden="true">{row.image?<img src={row.image} alt="" loading="lazy" onError={e=>{e.currentTarget.style.display="none";}}/>:<Newspaper size={38}/>}</a><div className={styles.cardBody}><div className={styles.meta}><span>{row.categories.find(c=>normalize(c)!=="noticias")||"Notícias"}</span><time dateTime={row.date}>{new Date(row.date).toLocaleDateString("pt-BR",{day:"2-digit",month:"short",year:"numeric"})}</time></div><h2><a href={row.url}>{row.title}</a></h2><p>{row.excerpt}</p><a className={styles.read} href={row.url}>Ler notícia <ArrowUpRight size={17}/></a></div></article>)}</div>:<div className={styles.empty}><Search size={32}/><h2>Nenhuma notícia encontrada</h2><p>Tente outro termo ou ajuste os filtros para encontrar o que procura.</p><Button variant="outline" onClick={clear}>Limpar filtros</Button></div>}
 {rows&&result.length>12&&<nav aria-label="Paginação das notícias" className={styles.pagination}><Button variant="outline" size="sm" disabled={current===1} onClick={()=>go(current-1)}><ChevronLeft size={16}/>Anterior</Button><span>Página <strong>{current}</strong> de {pages}</span><Button variant="outline" size="sm" disabled={current===pages} onClick={()=>go(current+1)}>Próxima<ChevronRight size={16}/></Button></nav>}
 </section>;
};

